function solve(n, arestas) {
  const adj = Array.from({ length: n }, () => []);
  const grau = new Array(n).fill(0);

  for (const [a, b] of arestas) {
    adj[a].push(b);
    grau[b]++;
  }

  const pq = [];
  for (let i = 0; i < n; i++) {
    if (grau[i] === 0) pq.push(i);
  }

  const ordem = [];

  while (pq.length) {
    const u = pq.shift();
    ordem.push(u);
    for (const v of adj[u]) {
      grau[v]--;
      if (grau[v] === 0) pq.push(v);
    }
    pq.sort((x, y) => x - y);
  }

  return ordem.length === n ? ordem : null;
}
